"""Spreadsheet formula engine per README.md."""

import re


class CycleError(Exception):
    pass


_TOKEN_RE = re.compile(
    r"\s*(?:(?P<number>\d+(?:\.\d+)?|\.\d+)"
    r"|(?P<ref>[A-Za-z]+\d*)"
    r"|(?P<op>[-+*/^()]))"
)


def _tokenize(text):
    tokens = []
    pos = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            if text[pos:].strip() == "":
                break
            raise ValueError(f"unexpected character {text[pos]!r} in formula")
        pos = m.end()
        if m.group("number") is not None:
            tokens.append(("number", float(m.group("number"))))
        elif m.group("ref") is not None:
            tokens.append(("ref", m.group("ref")))
        else:
            tokens.append(("op", m.group("op")))
    return tokens


class _Parser:
    """Recursive descent over the grammar:

    expr   := term (('+' | '-') term)*
    term   := unary (('*' | '/') unary)*
    unary  := '-' unary | power
    power  := atom ('^' unary)?          # right-associative; '-' looser than '^'
    atom   := number | ref | '(' expr ')'
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def take(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of formula")
        self.pos += 1
        return tok

    def parse(self):
        node = self.expr()
        if self.peek() is not None:
            raise ValueError(f"unexpected token {self.peek()!r}")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = (op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = (op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.power()

    def power(self):
        node = self.atom()
        if self.peek() == ("op", "^"):
            self.take()
            node = ("^", node, self.unary())
        return node

    def atom(self):
        kind, value = self.take()
        if kind == "number":
            return ("number", value)
        if kind == "ref":
            return ("ref", value)
        if (kind, value) == ("op", "("):
            node = self.expr()
            if self.take() != ("op", ")"):
                raise ValueError("expected ')'")
            return node
        raise ValueError(f"unexpected token {(kind, value)!r}")


def _eval_node(node, resolve):
    op = node[0]
    if op == "number":
        return node[1]
    if op == "ref":
        return resolve(node[1])
    if op == "neg":
        return -_eval_node(node[1], resolve)
    left = _eval_node(node[1], resolve)
    right = _eval_node(node[2], resolve)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        return left / right
    return left ** right


def evaluate(cells):
    asts = {}
    for name, text in cells.items():
        if text.startswith("="):
            asts[name] = _Parser(_tokenize(text[1:])).parse()
        else:
            asts[name] = ("number", float(text))

    values = {}
    in_progress = set()

    def resolve(name):
        if name in values:
            return values[name]
        if name in in_progress:
            raise CycleError(f"cycle detected involving cell {name!r}")
        if name not in asts:
            raise KeyError(f"unknown cell {name!r}")
        in_progress.add(name)
        try:
            values[name] = _eval_node(asts[name], resolve)
        finally:
            in_progress.discard(name)
        return values[name]

    return {name: resolve(name) for name in cells}

